using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class LatencyViewTest{
static EchoValue V(long n){return n>=0?new EchoValue{Ms=n}:new EchoValue{Error="TimedOut"};}
static IEnumerable<Control> Children(Control root){foreach(Control child in root.Controls){yield return child;foreach(var n in Children(child))yield return n;}}
static void Check(bool v,string what){if(!v)throw new Exception(what);}
[STAThread]static void Main(string[] args){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var s=new EchoStats(new[]{V(1),V(3),V(-1),V(21),V(15)});Check(s.Median==9&&s.Max==21&&s.Ok==4&&s.Sent==5&&s.Timeout==1,"Median/Antwortquote");Check(new EchoStats(new[]{V(-1)}).Median==null,"Timeout");
using(var f=new Atlas()){var type=typeof(Atlas);type.GetField("archive",flags).SetValue(f,args[0]);
var t=DateTime.Today.AddHours(8).ToUniversalTime().Ticks;var file=(string)type.GetMethod("PingPath",flags).Invoke(f,new object[]{DateTime.Today});Directory.CreateDirectory(Path.GetDirectoryName(file));var json=new JavaScriptSerializer();foreach(int sec in new[]{0,5,10,120,125}){var pair=new EchoPair{Time=t+sec*TimeSpan.TicksPerSecond,Session=sec<120?"a":"b",Router=V(1),Repeater=V(sec==125?-1:sec+2)};File.AppendAllText(file,json.Serialize(pair)+Environment.NewLine);}
f.Show();Application.DoEvents();Check(!((CheckBox)type.GetField("echoEnabled",flags).GetValue(f)).Checked,"opt-in");
foreach(int width in new[]{930,600}){Exception fail=null;f.BeginInvoke((Action)(()=>{var dlg=Application.OpenForms.Cast<Form>().Last();try{dlg.Size=new Size(width,480);dlg.PerformLayout();var views=Children(dlg).OfType<ListView>().ToList();var rows=views.Single(v=>v.Columns[0].Text=="Minute");Check(rows.Items.Count==3&&rows.Items[1].Text=="Messlücke","Lücke");Check(rows.Items[0].SubItems[2].Text.Contains("1/2"),"Quote");rows.Items[0].Selected=true;var detail=views.Single(v=>v!=rows);Check(detail.Items.Count==2&&detail.Items[1].SubItems[2].Text.Contains("Timeout"),"Details");Check(rows.ClientSize.Height>55&&detail.ClientSize.Height>55,"Platz");var graph=Children(dlg).OfType<EchoPlot>().Single();using(var bitmap=new Bitmap(graph.Width,graph.Height))graph.DrawToBitmap(bitmap,graph.ClientRectangle);}catch(Exception ex){fail=ex;}finally{dlg.Close();}}));type.GetMethod("ShowLatency",flags).Invoke(f,null);if(fail!=null)throw fail;}}
Console.WriteLine("OK");}}